static object F_c1_other_handoff_text(object v_id) {
if (R.Bool(R.eq(v_id,"ward"))) {
return "开锁的人已经核对了。出去以后，那把钥匙的来路还得写清楚。";
} else {
}
if (R.Bool(R.eq(v_id,"quer"))) {
return "我答了。你还要把我堵在这儿？门开了，让开一点。";
} else {
}
if (R.Bool(R.eq(v_id,"lucian"))) {
return "名字答对了，缘由还空着呢。沃德，留一行空白总比填错强。";
} else {
}
if (R.Bool(R.eq(v_id,"gu"))) {
return "门开了。先莫争，外面若有文书，读过再说。";
} else {
}
if (R.Bool(R.eq(v_id,"elena"))) {
return "我慢一点。阮清月……出去以后，你也别先走。";
} else {
}
if (R.Bool(R.eq(v_id,"ruan"))) {
return "我在这儿。你先扶住门框，等站稳了再迈那一步。";
} else {
}
if (R.Bool(R.eq(v_id,"selma"))) {
return "我的本子带上了。门内查到的，跟出去以后查到的，分开记。";
} else {
}
if (R.Bool(R.eq(v_id,"moran"))) {
return "外面的光不一样。等我站到门边再画，别挡着伊莲娜。";
} else {
}
if (R.Bool(R.eq(v_id,"mora"))) {
return "人先出去。试剂的事还没说清；有谁不舒服，别瞒着。";
} else {
}
if (R.Bool(R.eq(v_id,"veronica"))) {
return "取走一瓶东西和拿它做了什么，是两件事。先把原瓶找到。";
} else {
}
if (R.Bool(R.eq(v_id,"bertrand"))) {
return "我站门边。一个一个过去，先看落脚的地方。";
} else {
}
return "门框没歪。慢慢过，别拿身体去撞那道闩。";
}
